export const itemSprite = (type, material = 'past') => (WEAPONS[type] || ITEMS[type] || {})[material] || null;
export function decodeSprite(sp) {
  const col = new Array(sp.w * sp.h).fill(null);
  sp.r.forEach((row, y) => { let x = 0; row.replace(/(\D)(\d*)/g, (m, ch, n) => { const k = n ? +n : 1, i = ALPHA.indexOf(ch); if (i >= 0) for (let q = 0; q < k; q++) col[y * sp.w + x + q] = sp.p[i]; x += k; return m; }); });
  return { w: sp.w, h: sp.h, col };
}
export function spriteToCanvas(sp, scale = 1) {
  const c = document.createElement('canvas'); c.width = sp.w; c.height = sp.h;
  const x = c.getContext('2d'); decodeSprite(sp).col.forEach((h, i) => { if (h) { x.fillStyle = h; x.fillRect(i % sp.w, Math.floor(i / sp.w), 1, 1); } });
  Object.assign(c.style, { width: sp.w * scale + 'px', height: sp.h * scale + 'px', imageRendering: 'pixelated' });
  return c;
}
export function spriteSVG(sp) {
  let r = ''; sp.r.forEach((row, y) => { let x = 0; row.replace(/(\D)(\d*)/g, (m, ch, n) => { const k = n ? +n : 1, i = ALPHA.indexOf(ch); if (i >= 0) r += `<rect x="${x}" y="${y}" width="${k}" height="1" fill="${sp.p[i]}"/>`; x += k; return m; }); });
  return `<svg viewBox="0 0 ${sp.w} ${sp.h}" shape-rendering="crispEdges" style="width:100%;height:100%;display:block;image-rendering:pixelated" aria-hidden="true">${r}</svg>`;
}

