export const PART_ANIM = { fps: 4, frames: 4 };
export function composeParts(img,pm,states,frame){
 const w=img.w,h=img.h,col=img.col.slice(),f=(((frame||0)%4)+4)%4,H=[.3,.48,.64,.48][f];
 const hx=c=>[1,3,5].map(i=>parseInt(c.slice(i,i+2),16)),lum=c=>{const v=hx(c);return (.299*v[0]+.587*v[1]+.114*v[2])/255;};
 const mix=(a,b,t)=>{const A=hx(a),B=hx(b);return '#'+A.map((v,i)=>Math.round(v+(B[i]-v)*t).toString(16).padStart(2,'0')).join('');};
 let x0=w,y0=h,x1=-1,y1=-1;
 for(let i=0;i<w*h;i++){const c=img.col[i];if(!c)continue;const st=states[pm[i]]||'g',c7=c.slice(0,7),L=lum(c7);
  if(st==='g')col[i]=L<.32?'#A9A293':L<.62?'#C4BEAE':'#D3CEC0';
  else if(st==='n'){col[i]=mix(c7,L<.32?'#7A1A0C':L<.62?'#E0501E':'#FF9A3A',H);const x=i%w,y=(i/w)|0;if(x<x0)x0=x;if(x>x1)x1=x;if(y<y0)y0=y;if(y>y1)y1=y;}}
 if(x1>=0&&(f===1||f===2)){const P=f===1?[[x1+2,y0-1,'#FFF0A0'],[x0-2,y0+1,'#FFD040'],[x1+1,y1-2,'#FFD040']]:[[x1+3,y0-3,'#FFD040'],[x0-3,y0-1,'#FFF0A0'],[x0-1,y0-3,'#FFF0A0']];
  P.forEach(([x,y,c])=>{if(x>=0&&y>=0&&x<w&&y<h&&!col[y*w+x])col[y*w+x]=c;});}
 return {w,h,col};}
export function partMap(type) { const sp = PART_MAPS[type]; return sp ? decodeSprite(sp).col.map((v) => (v === null ? -1 : +v)) : null; }
// Fortschritt → Zustände: fertigeTeile 0–5 → z. B. 2 → 'bbngg' (höchstens ein 'n', direkt nach dem letzten fertigen Teil).
export function partStates(builtParts) { const b = Math.max(0, Math.min(5, builtParts | 0)); return 'b'.repeat(b) + (b < 5 ? 'n' : '') + 'g'.repeat(Math.max(0, 4 - b)); }
export function itemPartsImage(type, material = 'past', states = 'bbbbb', frame = 0) {
  const sp = itemSprite(type, material), pm = partMap(type); if (!sp || !pm) return null;
  return composeParts(decodeSprite(sp), pm, states, frame);
}
export function itemPartsCanvas(type, material = 'past', states = 'bbbbb', frame = 0, scale = 1) {
  const img = itemPartsImage(type, material, states, frame); if (!img) return null;
  const c = document.createElement('canvas'); c.width = img.w * scale; c.height = img.h * scale; const x = c.getContext('2d');
  img.col.forEach((h, i) => { if (h) { x.fillStyle = h; x.fillRect((i % img.w) * scale, Math.floor(i / img.w) * scale, scale, scale); } });
  return c;
}
