// ── Anzeige in festen Flächen (Schmiede 5.1/5.2, Kacheln „Noch nicht begonnen“) ──────────────
// Werkstück auf den sichtbaren Inhalt zuschneiden und in einer Fläche fester Größe mittig zeigen.
// Box = Vereinigung über alle Bauzustände und Animationsbilder – das Werkstück springt und wackelt dadurch nie.
export const FORGE_PANEL = { height: 176, weaponScale: 4, itemScale: 4, petScale: 3, tileHeight: 92, tileScale: 2 };
export function itemBounds(type, material = 'past') {
  let x0 = 1e9, y0 = 1e9, x1 = -1, y1 = -1;
  for (const st of ['ggggg', 'ngggg', 'bnggg', 'bbngg', 'bbbng', 'bbbbn', 'bbbbb']) for (let f = 0; f < PART_ANIM.frames; f++) {
    const img = itemPartsImage(type, material, st, f); if (!img) return null;
    img.col.forEach((c, i) => { if (!c) return; const x = i % img.w, y = (i / img.w) | 0; if (x < x0) x0 = x; if (y < y0) y0 = y; if (x > x1) x1 = x; if (y > y1) y1 = y; });
  }
  return { x: x0, y: y0, w: x1 - x0 + 1, h: y1 - y0 + 1 };
}
export function cropImage(img, box) { const col = new Array(box.w * box.h).fill(null); for (let y = 0; y < box.h; y++) for (let x = 0; x < box.w; x++) col[y * box.w + x] = img.col[(y + box.y) * img.w + x + box.x]; return { w: box.w, h: box.h, col }; }
// Wie itemPartsCanvas, aber zugeschnitten: in der Fläche mit display:flex; align-items:center; justify-content:center anzeigen.
export function itemPartsCanvasTrimmed(type, material = 'past', states = 'bbbbb', frame = 0, scale = 1) {
  const img = itemPartsImage(type, material, states, frame), box = itemBounds(type, material); if (!img || !box) return null;
  const im = cropImage(img, box), c = document.createElement('canvas'); c.width = im.w * scale; c.height = im.h * scale;
  const x = c.getContext('2d'); im.col.forEach((h, i) => { if (h) { x.fillStyle = h; x.fillRect((i % im.w) * scale, Math.floor(i / im.w) * scale, scale, scale); } });
  c.style.imageRendering = 'pixelated'; return c;
}
